import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    result_set = set()

    for i in range(n):
        current_or = 0
        for j in range(i, n):
            current_or |= a[j]
            result_set.add(current_or)

    print(len(result_set))

if __name__ == "__main__":
    main()
"}

