import sys

def can_sell_tickets(bills):
    """Determine if the clerk can sell tickets to all people."""
    count_25 = 0
    count_50 = 0

    for bill in bills:
        if bill == 25:
            count_25 += 1
        elif bill == 50:
            # Need to give 25 as change
            if count_25 > 0:
                count_25 -= 1
                count_50 += 1
            else:
                return "NO"
        elif bill == 100:
            # Try to give 1*50 + 1*25 first
            if count_50 > 0 and count_25 > 0:
                count_50 -= 1
                count_25 -= 1
            elif count_25 >= 3:
                count_25 -= 3
            else:
                return "NO"
    return "YES"

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    bills = list(map(int, data[1:1+n]))

    result = can_sell_tickets(bills)
    print(result)

if __name__ == "__main__":
    main()
"}

