import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    total_sum = sum(a)
    nice_indices = []

    for j in range(n):
        # Sum of array without element at index j
        S = total_sum - a[j]

        # Check if there exists an element x such that 2x == S
        found = False
        for k in range(n):
            if k != j and 2 * a[k] == S:
                found = True
                break

        if found:
            nice_indices.append(j + 1)  # 1-indexed

    print(len(nice_indices))
    if nice_indices:
        print(' '.join(map(str, nice_indices)))

if __name__ == "__main__":
    solve()
"}

