def longest_fibonacci_segment(n, a):
    max_len = 2  # Any segment of length 2 is good

    # Check all possible segments of length >= 3
    for i in range(n - 2):
        # Check if segment starting at i is good
        is_good = True
        for j in range(i + 2, n):
            if a[j] != a[j-1] + a[j-2]:
                is_good = False
                break
        if is_good:
            max_len = max(max_len, n - i)

    return max_len

