def solve():
    # Read input
    available = input().strip()
    m = int(input())

    # Parse available weights
    weights = []
    for i in range(10):
        if available[i] == '1':
            weights.append(i + 1)

    # Try to find a valid sequence using backtracking
    sequence = []

    def backtrack(pos, left_sum, right_sum, prev_weight):
        if pos == m:
            return True

        # Try all available weights
        for w in weights:
            if w == prev_weight:
                continue

            # Check if this weight can be placed on the current pan
            if pos % 2 == 0:  # Left pan
                # After placing on left, left should outweigh right
                new_left = left_sum + w
                if new_left > right_sum:
                    sequence.append(w)
                    if backtrack(pos + 1, new_left, right_sum, w):
                        return True
                    sequence.pop()
            else:  # Right pan
                # After placing on right, right should outweigh left
                new_right = right_sum + w
                if new_right > left_sum:
                    sequence.append(w)
                    if backtrack(pos + 1, left_sum, new_right, w):
                        return True
                    sequence.pop()

        return False

    if backtrack(0, 0, 0, -1):
        print("YES")
        print(' '.join(map(str, sequence)))
    else:
        print("NO")

solve()
"}

