def compute_grundy(n):
    if n == 0:
        return 0
    # Check all possible k (number of piles)
    max_k = 1000  # More than enough for n <= 100000
    moves = set()
    for k in range(2, max_k + 1):
        # Check if n can be split into k piles with arithmetic sequence of difference 1
        # a1 + (a1-1) + ... + (a1-(k-1)) = n
        # sum = k*a1 - (k-1)*k/2 = n
        sum_of_piles = k * n - (k - 1) * k
        if sum_of_piles < 0:
            break
        if sum_of_piles % n != 0:
            continue
        a1 = sum_of_piles // n
        # Check if a1 > a2 > ... > ak > 0
        if a1 <= k:
            continue
        # Valid split: a1, a1-1, ..., a1-(k-1)
        # Compute Grundy XOR of resulting piles
        xor_sum = 0
        for i in range(k):
            xor_sum ^= compute_grundy(a1 - i)
        moves.add(xor_sum)
    # Return mex (minimum excludant)
    mex = 0
    while mex in moves:
        mex += 1
    return mex

def solve(n):
    grundy = compute_grundy(n)
    if grundy == 0:
        return -1  # Gena wins
    # Find minimal k for Serozha to win
    for k in range(2, 1000 + 1):
        sum_of_piles = k * n - (k - 1) * k
        if sum_of_piles < 0:
