        if sum_of_piles % n != 0:
            continue
        a1 = sum_of_piles // n
        if a1 <= k:
            continue
        # Valid split, check if it leads to losing position for Gena
        xor_sum = 0
        for i in range(k):
            xor_sum ^= compute_grundy(a1 - i)
        if xor_sum == 0:
            return k
    return -1

