def solve():
    a, b = map(int, input().split())

    # BFS from 1
    from collections import deque

    visited = {}
    queue = deque([(1, 1)])  # (resistance, resistor_count)

    while queue:
        r, count = queue.popleft()

        if r == a / b:
            print(count)
            return

        # Series: r + 1
        if r + 1 not in visited or visited[r + 1] > count + 1:
            visited[r + 1] = count + 1
            queue.append((r + 1, count + 1))

        # Parallel: r / (r + 1)
        if r < 1 and r / (r + 1) not in visited or visited[r / (r + 1)] > count + 1:
            visited[r / (r + 1)] = count + 1
            queue.append((r / (r + 1), count + 1))

solve()
