def generate_expansions(pattern):
    """Generate all possible expansions of a pattern with '?'"""
    expansions = [""]
    for ch in pattern:
        if ch == '?':
            # '?' can be replaced by any of 'a'-'e' or be empty
            new_expansions = []
            for exp in expansions:
                for c in ['a', 'b', 'c', 'd', 'e', '']:
                    new_expansions.append(exp + c)
            expansions = new_expansions
        else:
            # Regular character, add it to all expansions
            expansions = [exp + ch for exp in expansions]
    return expansions

# Read input
import sys

words = set()
line = sys.stdin.readline()
while line:
    line = line.strip()
    if line:
        words.add(line)
    line = sys.stdin.readline()

# Read patterns and process
output = []
line = sys.stdin.readline()
while line:
    line = line.strip()
    if line:
        # Generate all possible expansions
        expansions = generate_expansions(line)

        # Count matches
        count = 0
        for exp in expansions:
            if exp in words:
                count += 1
        output.append(str(count))
    line = sys.stdin.readline()

# Print results
print("\n".join(output))
"}

