# Read stuffing information
stuffings = []
for _ in range(m):
    a, b, c, d = map(int, input().split())
    max_buns = min(a // b, n // c)
    stuffings.append((max_buns, c, d))  # (max_buns, dough_per_bun, tugriks_per_bun)

# dp[d] = maximum tugriks with d grams of dough
dp = [0] * (n + 1)

# Knapsack with multiple items of the same type
for max_buns, c, d in stuffings:
    for d_usage in range(n + 1):
        if dp[d_usage] > 0:
            for x in range(1, max_buns + 1):
                new_dough = d_usage + x * c
                if new_dough <= n:
                    new_tugriks = dp[d_usage] + x * d
                    if new_tugriks > dp[new_dough]:
                        dp[new_dough] = new_tugriks

# Consider plain buns at the end
for d_usage in range(n + 1):
    if dp[d_usage] > 0:
        plain_buns = (n - d_usage) // c0
        plain_tugriks = plain_buns * d0
        if dp[d_usage] + plain_tugriks > dp[n]:
            dp[n] = dp[d_usage] + plain_tugriks

print(dp[n])
