import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        a = list(map(int, [next(it) for _ in range(n)]))

        # Sort the array to find target positions
        sorted_a = sorted(a)

        # Check if it's possible
        possible = True
        for i in range(n):
            # Number of positions the element at index i needs to move
            move = abs(a[i] - sorted_a[i])

            # If an element needs to move an odd number of positions,
            # it will be swapped an odd number of times, ending up facing left
            if move % 2 == 1:
                possible = False
                break

        if possible:
            print("YES")
        else:
            print("NO")

if __name__ == "__main__":
    solve()
