def is_prime(n, primes):
    return n in primes

def largest_divisor(n):
    if n % 2 == 0:
        return 2
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return i
    return None

def solve():
    n = int(input())
    b = list(map(int, input().split()))

    # Find primes up to max(b)
    max_b = max(b)
    is_prime_list = [True] * (max_b + 1)
    is_prime_list[0] = is_prime_list[1] = False

    for i in range(2, int(max_b**0.5) + 1):
        if is_prime_list[i]:
            for j in range(i * i, max_b + 1, i):
                is_prime_list[j] = False

    primes = [i for i, is_p in enumerate(is_prime_list) if is_p]

    # Map prime to its index
    prime_to_index = {prime: i+1 for i, prime in enumerate(primes)}

    # Find all primes in b
    prime_indices = {idx: prime for idx, prime in enumerate(b) if is_prime_list[prime]}

    # For each element, check if it could be an original element
    original_elements = []

    # Try to match elements
    used = [False] * len(b)

    for i, val in enumerate(b):
        if not used[i]:
            if is_prime_list[val]:
                # Could be original element (val) or derived element (prime_index)
                # Check if there's a match for derived element
                if val in prime_to_index:
                    derived_index = prime_to_index[val]
                    # Find if there's an element at index j that corresponds to val
                    # as the derived element
                    for j, other_val in enumerate(b):
                        if not used[j] and other_val == derived_index:
                            original_elements.append(val)
                            used[i] = True
                            used[j] = True
                            break
            else:
                # Could be original element (val) or derived element (largest divisor)
                # Check if there's a match for derived element
                divisor = largest_divisor(val)
                if divisor:
                    for j, other_val in enumerate(b):
                        if not used[j] and other_val == divisor:
                            original_elements.append(val)
                            used[i] = True
                            used[j] = True
                            break

    print(original_elements)

solve()
