import sys

def draw_cardiogram(n, a):
    max_y = max(a)

    # For each y-level from 1 to max_y
    for y in range(1, max_y + 1):
        line = []

        # For each x-position from 1 to max_y
        for x in range(1, max_y + 1):
            # Check if we're at point (x, y)
            if a[x - 1] == y:
                line.append('/')
            # Check if we're at point (x+1, y)
            elif a[x] == y:
                line.append('\')
            else:
                line.append(' ')

        # Join the line and print
        print(''.join(line))

if __name__ == "__main__":
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit(0)

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    draw_cardiogram(n, a)
