n, m = map(int, input().split())
coordinates = list(map(int, input().split()))
types = list(map(int, input().split()))

# Extract taxi driver coordinates and their indices in the original list
# We need to know which taxi driver is which for output ordering
# The output order is by increasing coordinate

taxi_coords = []
for i in range(n + m):
    if types[i] == 1:
        taxi_coords.append((coordinates[i], i))  # (coordinate, original index)

# Sort by coordinate (and original index to break ties, though coordinates are unique)
taxi_coords.sort()

# Count how many riders go to each taxi driver (using original index for output ordering)
result = [0] * m

for i in range(n + m):
    rider_pos = coordinates[i]
    if types[i] == 1:
        continue  # Skip taxi drivers

    # Binary search for insertion point
    left, right = 0, len(taxi_coords)
    while left < right:
        mid = (left + right) // 2
        if taxi_coords[mid][0] < rider_pos:
            left = mid + 1
        else:
            right = mid

    # left is the insertion point
    candidates = []
    if left > 0:
        candidates.append(taxi_coords[left - 1])  # taxi before rider
    if left < len(taxi_coords):
        candidates.append(taxi_coords[left])      # taxi after rider

    # Find the closest candidate
    closest = None
    for taxi in candidates:
        dist = abs(taxi[0] - rider_pos)
        if closest is None:
            closest = taxi
        else:
            current_dist = abs(closest[0] - rider_pos)
            if dist < current_dist:
                closest = taxi
            elif dist == current_dist and taxi[0] < closest[0]:
                closest = taxi

    # Update the count for this taxi driver
    result[closest[1]] += 1

print(' '.join(map(str, result)))
