        candidates.append(taxi_coords[left])      # taxi after rider

    # Find the closest candidate
    closest = None
    for taxi in candidates:
        dist = abs(taxi - rider_pos)
        if closest is None:
            closest = taxi
        else:
            current_dist = abs(closest - rider_pos)
            if dist < current_dist:
                closest = taxi
            elif dist == current_dist and taxi < closest:
                closest = taxi

    # Find which index in sorted list this is
    # Since coordinates are unique and sorted, we can binary search again
    left, right = 0, len(taxi_coords)
    while left < right:
        mid = (left + right) // 2
        if taxi_coords[mid] < closest:
            left = mid + 1
        else:
            right = mid

    # left is now the index in the sorted list
    result[left] += 1

print(' '.join(map(str, result)))

