def solve():
    n, m = map(int, input().split())

    # Store all voters with their party and cost
    voters = []
    for _ in range(n):
        p, c = map(int, input().split())
        voters.append((p, c))

    # Sort voters by cost
    voters.sort(key=lambda x: x[1])

    min_cost = float('inf')

    # Try each possible number of votes for the United Party
    for target in range(0, n + 1):
        # We need at least target votes for party 1
        # And we need to ensure no other party has ≥ target votes

        # Take the cheapest target votes for party 1
        cost = 0
        needed = target

        for p, c in voters:
            if needed == 0:
                break
            if p == 1:
                # We already have this vote, no cost
                needed -= 1
            else:
                # We need to buy this vote to give to party 1
                cost += c
                needed -= 1

        # If we need more votes than there are voters, skip
        if needed > 0:
            continue

        # Now ensure no other party has ≥ target votes
        party_votes = {}  # Maps party index to count

        for p, c in voters:
            if p == 1:
                continue
            if p in party_votes:
                party_votes[p] += 1
            else:
                party_votes[p] = 1

        # Reduce parties that have too many votes
        for party in party_votes:
            if party_votes[party] >= target:
                # Need to reduce to target - 1
                needed_reduction = party_votes[party] - (target - 1)

                # Find the cheapest votes to buy from this party
                for p, c in voters:
                    if p == 1 or p != party:
                        continue
                    # Buy this vote
                    cost += c
                    needed_reduction -= 1
                    if needed_reduction == 0:
                        break

        min_cost = min(min_cost, cost)

    print(min_cost)

solve()
