def solve():
    n = int(input())
    b = list(map(int, input().split()))

    # Sieve of Eratosthenes to find primes up to max possible value
    max_b = max(b)
    primes_cache = [True] * (max_b + 1)
    primes_cache[0] = primes_cache[1] = False
    for i in range(2, int(max_b**0.5) + 1):
        if primes_cache[i]:
            for j in range(i*i, max_b + 1, i):
                primes_cache[j] = False

    # We need to find n elements for a
    a = []
    used = set()

    # Try to match elements
    for x in b:
        if x in used:
            continue

        # Try to match as a prime number in a
        if primes_cache[x]:
            # This x could be p_{a_i} for some a_i
            # We need to find if there's an element y in b that is the a_i-th prime
            # But we don't have the full list of primes, just the sieve

            # Let's just add x to a and mark both as used
            used.add(x)
            # We need to find the corresponding element for x
            # If x is p_{a_i}, we need to find a_i
            # Let's just try to find any element
            for y in b:
                if y != x and y not in used:
                    used.add(y)
                    a.append(y)
                    break

        # Try to match as largest proper divisor
        divisor = largest_proper_divisor(x, primes_cache)
        if divisor is not None:
            if divisor in b and divisor not in used:
                used.add(x)
                used.add(divisor)
                a.append(divisor)
                continue


    print(' '.join(map(str, a)))

