def solve():
    weights_str = input().strip()
    m = int(input())

    # Parse available weights
    available_weights = []
    for i in range(10):
        if weights_str[i] == '1':
            available_weights.append(i + 1)

    # Use BFS to find a valid sequence
    from collections import deque

    # State: (position, last_weight, left_sum, right_sum, sequence)
    queue = deque()

    # Initialize with all available weights as the first weight
    for w in available_weights:
        queue.append((1, w, w, 0, [w]))

    while queue:
        pos, last_weight, left_sum, right_sum, seq = queue.popleft()

        # If we've placed all weights, return success
        if pos == m:
            print("YES")
            print(' '.join(map(str, seq)))
            return

        # Determine which pan to place the next weight on
        if pos % 2 == 0:
            # Even position (0-indexed): left pan
            for w in available_weights:
                if w != last_weight:
                    new_left = left_sum + w
                    new_right = right_sum

                    # Check if left outweighs right
                    if new_left > new_right:
                        new_seq = seq + [w]
                        queue.append((pos + 1, w, new_left, new_right, new_seq))
        else:
            # Odd position: right pan
            for w in available_weights:
                if w != last_weight:
                    new_left = left_sum
                    new_right = right_sum + w

                    # Check if right outweighs left
                    if new_right > new_left:
