def solve():
    MOD = 10**9 + 7

    # Read input
    n, l, k = map(int, input().split())
    a = list(map(int, input().split()))

    # Calculate the set of remainders
    remainders = set()
    for ai in a:
        remainders.add(ai % n)

    # Convert to list for easier handling
    values = list(remainders)
    size = len(values)

    # dp[j][v] = number of non-decreasing subsequences of length j ending with value v
    dp = [{} for _ in range(k+1)]
    for v in values:
        dp[1][v] = 1

    # For subsequences of length > 1, we need to consider combinations
    for length in range(2, k+1):
        for v in values:
            count = 0
            for v_prev in values:
                if v_prev <= v:
                    count = (count + dp[length-1].get(v_prev, 0)) % MOD
            dp[length][v] = count

    # Total number of non-decreasing subsequences of length between 1 and k
    total = 0
    for length in range(1, k+1):
        for v in values:
            total = (total + dp[length].get(v, 0)) % MOD

    print(total)

