import sys
from collections import defaultdict

def matches(word, pattern):
    """Check if word matches pattern."""
    # Find all '?' positions in the pattern
    q_positions = [i for i, ch in enumerate(pattern) if ch == '?']

    # Get the length of the pattern (after replacing '?' with empty)
    pattern_length = len(pattern) - len(q_positions)

    # If word length doesn't match pattern length, skip
    if len(word) != pattern_length:
        return False

    # Compare character by character, skipping positions with '?'
    for i, ch in enumerate(pattern):
        if ch == '?':
            continue
        # Pattern character is not '?', so it must match the word character
        if word[i] != ch:
            return False

    return True

def count_matches(words, pattern):
    """Count how many words match the given pattern."""
    count = 0
    for word in words:
        if matches(word, pattern):
            count += 1
    return count

def main():
    data = sys.stdin.read().split()
