import sys

def solve() -> None:
    k = int(sys.stdin.readline())
    q = sys.stdin.readline().strip()

    # Try all possible ways to split q into k parts
    # We'll use recursion to try all possibilities

    def backtrack(pos: int, parts: list, first_chars: set) -> bool:
        """Backtrack to try splitting the string starting at position pos"""
        if pos == len(q):
            # We've reached the end of the string
            return len(parts) == k

        # Try to split here
        if len(parts) < k:
            # We can start a new part here
            char = q[pos]
            if char not in first_chars:
                first_chars.add(char)
                parts.append(char)
                if backtrack(pos + 1, parts, first_chars):
                    return True
                parts.pop()
                first_chars.remove(char)

        # Continue without splitting
        return backtrack(pos + 1, parts, first_chars)

    result = []
    if backtrack(0, [], set()):
        print("YES")
        for part in result:
            print(part)
    else:
        print("NO")

if __name__ == "__main__":
    solve()
"}

