    # Union-Find data structure
    parent = list(range(N + 1))  # 1-indexed

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            parent[root_y] = root_x

    # Process all edges with weight <= max_weight
    for u, v, d in edges:
        if d <= max_weight:
            union(u, v)

    # Check if we can form a perfect matching
    # Each factory (1..N) should be connected to exactly one airport (1..N)
    # We need to check if each node is connected to exactly one other node

    # Find all connected components
    components = {}
    for i in range(1, N + 1):
        root = find(i)
        if root not in components:
            components[root] = []
        components[root].append(i)

    # For each component, check if it contains exactly N nodes (one factory and one airport)
    # Actually, we need to check if each node is part of a component with exactly N nodes
    # and that nodes from different sets are connected

    # Check if each node is connected to exactly one other node
    # We need to ensure that we can pair each factory with an airport

