    # Actually, we need to check if we can form a perfect matching
    # This is equivalent to checking if the graph has a perfect matching
    # For a bipartite graph, we can check if we can match each factory to an airport

    # Let me use a simpler approach: try to build the matching

    # Create adjacency list
    adj = [[] for _ in range(N + 1)]
    for u, v, d in edges:
        if d <= max_weight:
            adj[u].append(v)

    # Try to find a perfect matching using DFS
    match_to = [-1] * (N + 1)  # match_to[airport] = factory

    def dfs(node, visited):
        if visited[node]:
            return False
        visited[node] = True
        for neighbor in adj[node]:
            if match_to[neighbor] == -1 or dfs(match_to[neighbor], visited):
