    # Create adjacency list
    adj = [[] for _ in range(N + 1)]
    for u, v, d in edges:
        if d <= max_weight:
            adj[u].append(v)

    # Try to find a perfect matching using DFS
    match_to = [-1] * (N + 1)  # match_to[airport] = factory

    def dfs(node, visited):
        if visited[node]:
            return False
        visited[node] = True
        for neighbor in adj[node]:
            if match_to[neighbor] == -1:
                match_to[neighbor] = node
                return True
            else:
                # Already matched, try to find an alternate path
                if dfs(match_to[neighbor], visited):
                    match_to[neighbor] = node
                    return True
        return False

    # Try to match each factory
    for i in range(1, N + 1):
        if match_to[i] == -1:
            visited = [False] * (N + 1)
            if not dfs(i, visited):
                return False

    return True

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1

    edges = []
    for _ in range(M):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        d = int(data[idx]); idx += 1
        edges.append((u, v, d))

    # Binary search on the answer
    left = 1
    right = 10**9
    answer = -1

    while left <= right:
        mid = (left + right) // 2

        if can_form_perfect_matching(N, edges, mid):
            answer = mid
            right = mid - 1
        else:
            left = mid + 1

    print(answer)

if __name__ == "__main__":
    solve()

