# Handle k = 0 separately
if k == 0:
    for count in freq.values():
        if count >= 2:
            result += count * (count - 1) // 2
else:
    # For each pair of numbers where x < y
    for x in freq:
        for y in freq:
            if x < y:
                diff = count_diff_bits(x, y)
                if diff == k:
                    result += freq[x] * freq[y]

print(result)
