import sys

def solve(s, x):
    if (s - x) % 2 != 0 or s < x:
        return 0
    carry = (s - x) // 2
    if (x & carry) != 0:
        return 0
    k = bin(x).count('1')
    if carry == 0:
        return 2**k - 2
    else:
        return 2**k

