import sys
from collections import defaultdict

def has_perfect_matching(adj, n):
    """Check if there's a perfect matching in the graph."""
    # We need to match all n nodes
    # Use Union-Find to find connected components
    parent = {}

    def find(u):
        if u not in parent:
            parent[u] = u
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_v] = root_u

    # Union all connected nodes
    for u in adj:
        for v in adj[u]:
            union(u, v)

    # Check if we can form a perfect matching
    # A perfect matching requires that each component has even size
    # and we can pair them up
    for u in adj:
        root = find(u)
        size = 0
        for v in adj:
            if find(v) == root:
                size += 1
        if size % 2 != 0:
            return False

    return True

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    edges = []

    # Store edges by build time
    build_time_edges = defaultdict(list)
    for _ in range(M):
        u = int(next(it))
        v = int(next(it))
        d = int(next(it))
        edges.append((d, u, v))
        build_time_edges[d].append((u, v))

    # Sort edges by build time
    edges.sort()

    # Build adjacency list
    adj = defaultdict(list)

    # Try each build time in increasing order
    for d, u, v in edges:
        # Add all edges with this build time
        for uu, vv in build_time_edges[d]:
            adj[uu].append(vv)
            adj[vv].append(uu)

        # Check if we can form a perfect matching
        if has_perfect_matching(adj, N):
            print(d)
            return

    # If no perfect matching found
    print(-1)

if __name__ == "__main__":
    solve()
"}

