import sys

def is_s_palindrome(s):
    n = len(s)
    if n % 2 == 0:
        return False  # Even length strings are not s-palindromes
    mid = n // 2
    for i in range(mid + 1):
        if s[i] != s[n - 1 - i]:
            return False
    return True

def main():
    s = sys.stdin.readline().strip()
    if is_s_palindrome(s):
        print("TAK")
    else:
        print("NIE")

if __name__ == "__main__":
    main()
