import sys

def count_set_bits(x):
    """Count the number of bits that are set in x."""
    count = 0
    while x:
        count += 1
        x &= x - 1
    return count

def solve() -> None:
    s, x = map(int, sys.stdin.readline().split())

    # Check if s is greater than x and (s - x) is even
    if s <= x or (s - x) % 2 != 0:
        print(0)
        return

    y = (s - x) // 2

    # Count the number of bits set in x
    bits = count_set_bits(x)

    if x > 0:
        if y > 0:
            # If y > 0, all 2^bits distributions are valid
            print(1 << bits)
        else:
            # If y = 0, we need to subtract the cases where a = 0 or b = 0
            # For each bit set in x, we can assign all to a or all to b
            # This results in 2^bits - 2 valid distributions
            print((1 << bits) - 2)
    else:
        # x == 0, y must be > 0 for a and b to be positive
        if y > 0:
            print(1)
        else:
            print(0)

if __name__ == "__main__":
    solve()
"}

