import sys

def mod_pow(base, exp, mod):
    """Calculate (base^exp) % mod efficiently"""
    result = 1
    base = base % mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp //= 2
    return result

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    b, n, c = map(int, data)

    # Calculate total numbers modulo c
    term1 = (b - 1) % c
    term2 = mod_pow(b, n - 1, c)
    total_mod = (term1 * term2) % c

    if total_mod == 0:
        last_page = c
    else:
        last_page = total_mod

    print(last_page)

if __name__ == "__main__":
    solve()
"}

