import sys

def construct_graph(n, p):
    edges = []

    # Start with a simple structure where vertex i is connected to vertices i+1 through n
    # But we need to limit the total number of edges to 2n + p
    # Let's just connect vertex 1 to all other vertices, and then add edges between other vertices

    # Connect vertex 1 to all other vertices
    for i in range(2, n + 1):
        edges.append((1, i))

    # Connect other vertices in a chain-like pattern
    for i in range(2, n + 1):
        for j in range(i + 1, n + 1):
            if len(edges) < 2 * n + p:
                edges.append((i, j))
            else:
                break

    return edges

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        p = int(data[idx + 1])
        idx += 2

        graph = construct_graph(n, p)

        results.extend(graph)

    sys.stdout.write("\n".join(f"{u} {v}" for u, v in results))

if __name__ == "__main__":
    solve()
