def can_place(weights, m):
    """Check if it's possible to place m weights following the rules"""
    # Parse weights string
    available_weights = [i+1 for i, has_weight in enumerate(weights) if has_weight]

    # Use backtracking with memoization
    from functools import lru_cache

    def backtrack(pos, left, right, last_weight):
        if pos == m:
            return True, []  # Found a valid sequence

        # Try each available weight in descending order
        for weight in sorted(available_weights, reverse=True):
            if weight == last_weight:
                continue  # Skip consecutive duplicates

            # Determine which pan to place on
            if pos % 2 == 0:
                # Even position (0-indexed): place on right
                new_right = right + weight
                if new_right > left:
                    result, sequence = backtrack(pos + 1, left, new_right, weight)
                    if result:
                        return True, [weight] + sequence
            else:
                # Odd position: place on left
                new_left = left + weight
                if new_left > right:
                    result, sequence = backtrack(pos + 1, new_left, right, weight)
                    if result:
                        return True, [weight] + sequence

        return False, []

    # Start from position 0 with both pans empty
    success, sequence = backtrack(0, 0, 0, None)
    return success, sequence

