import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Directions: 1 means right, 0 means left
        dir = [1] * n

        # Check if already sorted
        sorted = True
        for i in range(n - 1):
            if a[i] > a[i + 1]:
                sorted = False
                break

        if sorted:
            # Already sorted, check if all directions are right
            if all(d == 1 for d in dir):
                print("YES")
            else:
                print("NO")
            continue

        # Simulate sorting with bubble sort
        # Create list of (value, direction)
        arr = [(a[i], dir[i]) for i in range(n)]

        # Bubble sort
        for i in range(n - 1):
            for j in range(n - 1 - i):
                if arr[j][0] > arr[j + 1][0]:
                    # Swap
                    arr[j], arr[j + 1] = arr[j + 1], arr[j]
                    # Flip directions
                    arr[j] = (arr[j][0], 1 - arr[j][1])
                    arr[j + 1] = (arr[j + 1][0], 1 - arr[j + 1][1])

        # Check if sorted
        sorted = True
        for i in range(n - 1):
            if arr[i][0] > arr[i + 1][0]:
                sorted = False
                break

        if sorted:
            # Check if all directions are right
            if all(d == 1 for (v, d) in arr):
                print("YES")
            else:
                print("NO")
        else:
            print("NO")

solve()
