pairs = []
for i in range(n):
    for j in range(i + 1, n):
        if a[i] == a[j]:
            pairs.append((i, j))

# For each pair, find the best contiguous subarray that includes i and j
best_sum = float('-inf')
best_indices = []

for i, j in pairs:
    # Start from i and include as far right as possible with positive values
    r = i
    while r <= j and (r == i or r == j or a[r] > 0):
        r += 1

    # Start from j and include as far left as possible with positive values
    l = j
    while l >= i and (l == i or l == j or a[l] > 0):
        l -= 1

    # The subarray is from l to r-1
    # We need to include l and r-1, and we can include any positive values between
    # but we cannot cut the first or last tree (l or r-1)

    # Let's just try all possible contiguous subarrays that include i and j
    for start in range(i, r):
        for end in range(l, j + 1):
            if a[start] == a[end]:
                # Calculate sum of this subarray
                current_sum = sum(a[start:end+1])
                if current_sum > best_sum:
                    best_sum = current_sum
                    best_indices = list(range(start, end + 1))

