def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Compute prefix sums
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + a[i]

    # Set to track broken positions
    broken = set()

    # Set of all zero-sum segments
    zero_segments = set()
    for i in range(n):
        for j in range(i, n):
            if prefix[j + 1] == prefix[i]:
                zero_segments.add((i, j))

    # Greedy: always break the segment that starts at the earliest position
    # and hasn't been broken yet
    for i in range(n):
        if i in broken:
            continue

        # Find the farthest j such that sum from i to j is 0
        farthest = i
        for j in range(i, n):
            if prefix[j + 1] == prefix[i]:
                farthest = j

        # Break this segment by inserting between i and i+1
        broken.add(i)

    print(len(broken))

solve()
