import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    idx = 0
    t = int(data[idx])
    idx += 1

    results = []
    for _ in range(t):
        n = int(data[idx])
        idx += 1

        # Read matrix a
        a = []
        for _ in range(n):
            a.append(data[idx])
            idx += 1

        # Skip empty line
        while idx < len(data) and data[idx] == '':
            idx += 1

        # Read matrix b
        b = []
        for _ in range(n):
            b.append(data[idx])
            idx += 1

        # Calculate differing bits
        diff = 0
        for i in range(n):
            for j in range(n):
                if a[i][j] != b[i][j]:
                    diff += 1

        # Check condition
        if n % 2 == 1:
            # Always possible
            results.append("YES")
        else:
            # Possible only if even number of differing bits
            if diff % 2 == 0:
                results.append("YES")
            else:
                results.append("NO")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

