def solve():
    n = int(input())

    # We start with coefficient 1 (from eax)
    # Each operation gives us a new coefficient that is a sum of existing coefficients
    # multiplied by constants from {1, 2, 4, 8}

    # BFS: each state is a set of coefficients we can reach
    # We want to find the minimum number of operations to get n

    from collections import deque

    # Initial state: we have coefficient 1 in 0 operations
    initial_state = {1}

    # Queue for BFS
    queue = deque([(initial_state, 0)])

    # Track visited states to avoid cycles
    visited = {frozenset(initial_state): 0}

    while queue:
        current_coeff_set, ops = queue.popleft()

        # Try all possible operations from this state
        for k in [1, 2, 4, 8]:
            # Operation 1: lea x, [k * coeff_register]
            new_coeff = k * max(current_coeff_set)  # Use the largest coefficient
            new_state = current_coeff_set | {new_coeff}

            if frozenset(new_state) not in visited:
                visited[frozenset(new_state)] = ops + 1
                queue.append((new_state, ops + 1))

            # Operation 2: lea x, [coeff_register + k * other_coeff_register]
            # Try all pairs of coefficients
            for coeff1 in current_coeff_set:
                for coeff2 in current_coeff_set:
                    new_coeff = coeff1 + k * coeff2
                    new_state = current_coeff_set | {new_coeff}

                    if frozenset(new_state) not in visited:
                        visited[frozenset(new_state)] = ops + 1
                        queue.append((new_state, ops + 1))


        # Check if we've reached n
        if n in current_coeff_set:
            print(ops)
            return

solve()
