    # Dictionary to store known values
    known = {}

    # Ask about all elements
    for i in range(1, n + 1):
        if i not in known:
            sys.stdout.write(f'? {i}\n')
            sys.stdout.flush()

            while True:
                try:
                    line = sys.stdin.readline()
                    if not line:
                        break
                    parts = list(map(int, line.split()))
                    if len(parts) < 2:
                        break
                    value, next_ = parts[0], parts[1]
                    break
                except Exception as e:
                    # Handle EOF or error
                    print(f"Error: {str(e)}")
                    sys.stdout.write("! -1\n")
                    sys.stdout.flush()
                    return

        known[i] = (value, next_)

    # Traverse from start to find minimum value >= x
    ans = -1
    current = start
    while True:
        value, next_ = known[current]
        if value >= x:
            ans = value
            break

        if next_ == -1:
            break
        current = next_ 

    sys.stdout.write(f'! {ans}\n')
    sys.stdout.flush()

