{"code": "import heapq

def solve():
    n, L = map(int, input().split())
    ramps = []
    for i in range(n):
        xi, di, ti, pi = map(int, input().split())
        ramps.append((xi, di, ti, pi, i + 1))  # i+1 is 1-indexed

    # Dijkstra's algorithm
    dist = [float('inf')] * (L + 1)
    prev = [None] * (L + 1)
    dist[0] = 0

    heap = [(0, 0)]  # (time, position)

    while heap:
        time, pos = heapq.heappop(heap)

        if pos == L:
            break

        if time > dist[pos]:
            continue

        # Move to pos + 1
        if pos + 1 <= L:
            if dist[pos + 1] > time + 1:
                dist[pos + 1] = time + 1
                prev[pos + 1] = pos
                heapq.heappush(heap, (time + 1, pos + 1))

        # Consider using ramps that can be used from this position
        for xi, di, ti, pi, idx in ramps:
            # pos must be >= xi - pi and <= xi
            if xi - pi <= pos and xi >= pos:
                # Also ensure we don't start gathering before 0
                if xi - pi >= 0:
                    new_pos = xi + di
                    new_time = time + pi + ti
                    if dist[new_pos] > new_time:
                        dist[new_pos] = new_time
                        prev[new_pos] = (pos, idx)  # Track ramp used
                        heapq.heappush(heap, (new_time, new_pos))

    # Reconstruct path
    path = []
    pos = L
    while pos != 0:
        if prev[pos] is None:
            break  # No path found
        if isinstance(prev[pos], tuple):
            # We used a ramp
            _, idx = prev[pos]
            path.append(idx)
            pos = prev[pos][0]
        else:
            pos = prev[pos]

    path.reverse()

    print(dist[L])
    print(len(path))
    if path:
        print(' '.join(map(str, path)))

solve()
