import sys

def solve(x, y, z):
    if z == 0:
        return 0, 0  # Avoid division by zero, though z >= 1 per problem statement

    max_coconuts = 0
    min_exchange = 0

    # Check all possible values of a from 0 to min(x, y)
    for a in range(0, min(x, y) + 1):
        # Sasha gives a to Masha
        sasha_gives = (x - a) // z + (y + a) // z

        # Masha gives a to Sasha
        masha_gives = (x + a) // z + (y - a) // z

        current_max = max(sasha_gives, masha_gives)

        if current_max > max_coconuts:
            max_coconuts = current_max
            # Choose the minimum exchange for this max
            if sasha_gives > masha_gives:
                min_exchange = a
            else:
                min_exchange = a  # Actually, a is same in both cases!
        elif current_max == max_coconuts:
            # Choose the minimum a
            if sasha_gives > masha_gives:
                min_exchange = min(min_exchange, a)
            else:
                min_exchange = min(min_exchange, a)

    return max_coconuts, min_exchange

