def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    r = int(data[1])
    k = int(data[2])
    a = list(map(int, data[3:3+n]))

    # Calculate current defense levels using sliding window
    defense = [0] * n
    for i in range(n):
        # Archers at position i cover from max(0, i-r) to min(n-1, i+r)
        start = max(0, i - r)
        end = min(n - 1, i + r)
        for j in range(start, end + 1):
            defense[j] += a[i]

    # Binary search
    low, high = 0, max(defense) + k

    def is_possible(target):
        additional = [0] * n
        for i in range(n):
            if defense[i] < target:
                need = target - defense[i]
                additional[i] = need

        # Distribute from right to left
        for i in range(n - 1, -1, -1):
            if additional[i] == 0:
                continue

            # Place additional[i] archers at position i (covers i-r to i+r)
