import sys

def solve():
    n = int(sys.stdin.readline())
    patterns = [sys.stdin.readline().strip() for _ in range(n)]
    length = len(patterns[0])

    result = []

    for i in range(length):
        # Collect all characters (excluding '?') at this position
        chars = set()
        for j in range(n):
            if patterns[j][i] != '?':
                chars.add(patterns[j][i])

        if len(chars) == 1:
            # All patterns have the same character at this position
            result.append(chars.pop())
        else:
            # Need '?', because there's no single character common to all
            result.append('?')

    print(''.join(result))

if __name__ == "__main__":
    solve()
