import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    N = int(data[idx])
    M = int(data[idx + 1])
    idx += 2

    words = []
    for _ in range(N):
        words.append(data[idx])
        idx += 1

    results = []

    for _ in range(M):
        pattern = data[idx]
        idx += 1

        # Generate all variations of the pattern
        variations = {pattern}
        for i, ch in enumerate(pattern):
            if ch == '?':
                # Replace this '?' with all possible characters (a-e) and with removal
                new_variations = set()
                for var in variations:
                    # Replace with character
                    for c in 'abcde':
                        new_variations.add(var[:i] + c + var[i+1:])
                    # Remove the '?'
                    new_variations.add(var[:i] + var[i+1:])
                variations = new_variations

        # Count matches
        count = 0
        for var in variations:
            count += sum(1 for word in words if word == var)

        results.append(str(count))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
