import sys

lines = sys.stdin.readlines()
if not lines:
    sys.exit()

n = int(lines[0].split()[0])
k = int(lines[0].split()[1])

# Build adjacency list
adj = [[] for _ in range(n + 1)]
for i in range(1, n):
    u, v = map(int, lines[i].split())
    adj[u].append(v)
    adj[v].append(u)

# Count pairs at distance k
# Use DFS from each node
count = 0

for start in range(1, n + 1):
    stack = [(start, 0, -1)]  # (vertex, distance, parent)

    while stack:
        vertex, dist, parent = stack.pop()

        if dist == k:
            count += 1

        if dist < k:
            for neighbor in adj[vertex]:
                if neighbor != parent:
                    stack.append((neighbor, dist + 1, vertex))

# Each pair is counted twice, so divide by 2
print(count // 2)
