import sys

lines = sys.stdin.read().split()
if not lines:
    sys.exit()

n = int(lines[0].split()[0])
k = int(lines[0].split()[1])

# Build adjacency list
adj = [[] for _ in range(n + 1)]
for i in range(1, n):
    u, v = map(int, lines[i].split())
    adj[u].append(v)
    adj[v].append(u)

# Count pairs at distance k
# Use BFS from each node
from collections import deque

count = 0

for start in range(1, n + 1):
    queue = deque([(start, 0, -1)])  # (vertex, distance, parent)

    while queue:
        vertex, dist, parent = queue.popleft()

        if dist == k:
            count += 1

        if dist < k:
            for neighbor in adj[vertex]:
                if neighbor != parent:
                    queue.append((neighbor, dist + 1, vertex))

# Each pair is counted twice, so divide by 2
print(count // 2)
"}

