def compute_grundy(n):
    """Compute the Grundy number for a pile of size n"""
    if n == 0:
        return 0  # Terminal position
    grundy_set = set()

    # Try all possible k (number of piles)
    for k in range(2, n + 1):
        # Calculate a such that a + (a-1) + ... + (a-k+1) = n
        # Sum = k*a - k*(k-1)/2 = n
        numerator = n + k * (k - 1) // 2
        if numerator % k == 0:
            a = numerator // k

            # Check if a > a-1 > ... > 0
            if a > 0:
                # Create the new piles
                piles = [a - i for i in range(k)]

                # Calculate the Grundy number of the resulting state
                # The resulting state is the XOR of Grundy numbers of all piles
                g = 0
                for pile in piles:
                    g ^= compute_grundy(pile)

                grundy_set.add(g)

    # Return mex
    mex = 0
    while mex in grundy_set:
        mex += 1
    return mex

def solve():
    n = int(input())

    # Compute Grundy number for the starting position
    g = compute_grundy(n)

    if g == 0:
        print(-1)  # Gena wins
    else:
        # Find the minimal k for which Grundy number is non-zero
        for k in range(2, n + 1):
            numerator = n + k * (k - 1) // 2
            if numerator % k == 0:
                a = numerator // k
                if a > 0:
                    # Create the new piles
                    piles = [a - i for i in range(k)]

                    # Calculate the Grundy number of the resulting state
                    g_result = 0
                    for pile in piles:
                        g_result ^= compute_grundy(pile)

                    if g_result != 0:
                        print(k)
                        return
        print(-1)

solve()
