def simulate_pushes(n, initial):
    """Simulate pushing the button and return the sequence after each push"""
    result = [initial.copy()]

    # Simulate pushing the button until we see a repeat or get the target
    seen = {tuple(initial): 0}
    target = list(range(n))

    while True:
        # Push the button
        new_sequence = initial.copy()

        for i in range(n):
            if i % 2 == 0:  # odd-indexed gears (1-indexed) rotate clockwise
                new_sequence[i] = (new_sequence[i] + 1) % n
            else:  # even-indexed gears rotate counter-clockwise
                new_sequence[i] = (new_sequence[i] - 1) % n

        # Check if we've seen this sequence before
        seq_tuple = tuple(new_sequence)
        if seq_tuple in seen:
            # We've seen this sequence before, we'll cycle
            cycle_length = seen[seq_tuple]
            # Check if we can get the target in this cycle
            for i in range(cycle_length):
                if result[i] == target:
                    return i + 1
            return -1  # Target not in this cycle

        seen[seq_tuple] = len(result)
        result.append(new_sequence)

        # Check if we've found the target
        if new_sequence == target:
            return len(result) - 1

        # Limit to avoid infinite loop (shouldn't be needed)
        if len(result) > 2 * n:
            return -1

n = int(input())
